do $boot$ begin if to_regprocedure('public.qb_backend_acceptance()') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_backend_acceptance()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_missing_tables text[];
    v_missing_functions text[];
    v_rls_failures text[];
begin

    -- --------------------------------------------------------
    -- REQUIRED TABLES
    -- --------------------------------------------------------

    select array_agg(required_name)
    into v_missing_tables

    from (
        select unnest(
            array[
                'profiles',
                'student_profiles',
                'teacher_profiles',
                'sponsor_profiles',

                'tenants',
                'tenant_memberships',

                'questions',
                'question_options',
                'question_media',

                'question_banks',
                'question_bank_items',

                'assessments',
                'assessment_questions',
                'attempts',
                'responses',
                'assessment_results',
                'gradebook',

                'classes',
                'class_memberships',
                'assignments',

                'marketplace_sellers',
                'marketplace_products',
                'orders',
                'order_items',
                'seller_earnings',
                'payouts',
                'entitlements',

                'competitions',
                'competition_institutions',
                'competition_teams',
                'competition_team_members',
                'competition_results',
                'competition_sponsors',

                'analytics_events',
                'daily_metrics',

                'support_tickets',
                'audit_logs',
                'system_events'
            ]
        ) as required_name
    ) required

    where not exists (
        select 1
        from information_schema.tables t
        where t.table_schema = 'public'
          and t.table_name =
                required.required_name
    );


    -- --------------------------------------------------------
    -- REQUIRED RPCs
    -- --------------------------------------------------------

    select array_agg(required_name)
    into v_missing_functions

    from (
        select unnest(
            array[
                'qb_get_questions',
                'qb_start_attempt',
                'qb_get_attempt',
                'qb_save_response',
                'qb_submit_attempt',
                'qb_get_result',
                'qb_get_attempt_review',

                'qb_admin_platform_overview',
                'qb_tenant_dashboard',
                'qb_tenant_learning_metrics',

                'qb_create_marketplace_order',
                'qb_settle_paid_order',
                'qb_seller_balance',
                'qb_request_payout',

                'qb_register_competition_school',
                'qb_create_competition_team',
                'qb_add_team_member',
                'qb_record_competition_result',
                'qb_finalize_competition_leaderboard',
                'qb_competition_leaderboard'
            ]
        ) as required_name
    ) required

    where not exists (
        select 1
        from information_schema.routines r
        where r.routine_schema = 'public'
          and r.routine_name =
                required.required_name
    );


    -- --------------------------------------------------------
    -- CRITICAL RLS CHECK
    -- --------------------------------------------------------

    select array_agg(required_name)
    into v_rls_failures

    from (
        select unnest(
            array[
                'questions',
                'assessment_questions',
                'attempts',
                'responses',
                'assessment_results',

                'tenants',
                'tenant_memberships',

                'marketplace_products',
                'orders',

                'competition_teams',
                'competition_results',

                'analytics_events'
            ]
        ) as required_name
    ) required

    where not exists (
        select 1
        from pg_tables p
        where p.schemaname = 'public'
          and p.tablename =
                required.required_name
          and p.rowsecurity = true
    );


    return jsonb_build_object(

        'status',
            case
                when
                    coalesce(
                        array_length(
                            v_missing_tables,
                            1
                        ),
                        0
                    ) = 0

                    and

                    coalesce(
                        array_length(
                            v_missing_functions,
                            1
                        ),
                        0
                    ) = 0

                    and

                    coalesce(
                        array_length(
                            v_rls_failures,
                            1
                        ),
                        0
                    ) = 0

                then 'PASS'

                else 'FAIL'
            end,

        'release',
            'QB-BACKEND-FINAL-1',

        'missing_tables',
            coalesce(
                to_jsonb(v_missing_tables),
                '[]'::jsonb
            ),

        'missing_functions',
            coalesce(
                to_jsonb(v_missing_functions),
                '[]'::jsonb
            ),

        'rls_failures',
            coalesce(
                to_jsonb(v_rls_failures),
                '[]'::jsonb
            ),

        'checked_at',
            now()
    );

end;
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_can_manage_institution(uuid)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_can_manage_institution(p_institution_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        public.qb_is_platform_admin()
        or exists (
            select 1
            from public.institution_memberships im
            where im.institution_id = p_institution_id
              and im.user_id = auth.uid()
              and upper(im.status::text) = 'ACTIVE'
              and upper(im.role::text) in (
                  'OWNER',
                  'ADMIN',
                  'ADMINISTRATOR',
                  'HEAD_TEACHER',
                  'HEADTEACHER'
              )
        );
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_get_question_media(uuid)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_get_question_media(p_question_id uuid)
 RETURNS TABLE(media_asset_id uuid, usage_type text, option_key text, display_order integer, storage_bucket text, storage_path text, media_type text, mime_type text, width integer, height integer, alt_text text, caption text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        ma.id,
        qm.usage_type,
        qm.option_key,
        qm.display_order,

        ma.storage_bucket,
        ma.storage_path,

        ma.media_type,
        ma.mime_type,

        ma.width,
        ma.height,

        ma.alt_text,
        ma.caption
    from public.question_media qm
    join public.media_assets ma
        on ma.id = qm.media_asset_id
    join public.questions q
        on q.id = qm.question_id
    where
        qm.question_id = p_question_id
        and q.status = 'active'
        and ma.status = 'ACTIVE'
    order by qm.display_order;
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_get_question_options(uuid)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_get_question_options(p_question_id uuid)
 RETURNS TABLE(id uuid, option_key text, display_order integer, content jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        qo.id,
        qo.option_key,
        qo.display_order,
        qo.content
    from public.question_options qo
    join public.questions q
        on q.id = qo.question_id
    where
        qo.question_id = p_question_id
        and q.status = 'active'
    order by qo.display_order;
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_has_permission(text)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_has_permission(p_permission_code text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        public.qb_is_platform_admin()
        or exists (
            select 1
            from public.role_permissions rp
            join public.permissions p
              on p.id = rp.permission_id
            where upper(rp.role) = public.qb_current_role()
              and upper(p.code) = upper(p_permission_code)
              and rp.allowed = true
        );
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_marketplace_catalog()') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_marketplace_catalog()
 RETURNS TABLE(id uuid, product_type text, title text, description text, subject_code text, grade text, license_type text, price numeric, currency text, seller_display_name text, seller_verification_status text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        mp.id,
        mp.product_type,
        mp.title,
        mp.description,
        mp.subject_code,
        mp.grade,
        mp.license_type,
        mp.price,
        mp.currency,
        ms.display_name,
        ms.verification_status,
        mp.created_at
    from public.marketplace_products mp
    join public.marketplace_sellers ms
      on ms.id = mp.seller_id
    where upper(mp.status) = 'PUBLISHED'
      and upper(mp.moderation_status) = 'APPROVED'
      and upper(ms.status) = 'ACTIVE'
    order by mp.created_at desc;
$function$
$qb_bootstrap$; end if; end $boot$;

commit;
